import{_ as i,l as t,o as n,c as l,v as e,p as s,x as o,d as h,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Nano Banana 2","description":"","frontmatter":{"title":"Nano Banana 2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nano-banana-2.md","filePath":"llm/nano-banana-2.md","lastUpdated":1789023840000}'),g={name:"llm/nano-banana-2.md"};function p(P,a,c,B,A,E){const r=t("Mermaid");return n(),l("div",null,[a[1]||(a[1]=e('<h1 id="nano-banana-2" tabindex="-1">Nano Banana 2 <a class="header-anchor" href="#nano-banana-2" aria-label="Permalink to &quot;Nano Banana 2&quot;">​</a></h1><div class="epigraph"><p>把 Pro 档的世界知识、规格与主体一致性，放到 Flash 的速度上：Gemini 3.1 Flash Image 成为这一代默认出图模型。</p><footer>—— Raisinghani，Nano Banana 2: Google’s latest AI image generation model，Google Blog，2026-02-26</footer></div><p>Google 在 2026 年 2 月 26 日发布 <strong>Nano Banana 2</strong>，技术名 <strong>Gemini 3.1 Flash Image</strong>。产品经理 Naina Raisinghani 的博客把定位写成：2025 年 8 月 Gemini 图像模型 Nano Banana 走红，11 月的 <strong>Nano Banana Pro</strong>（Gemini 3 Pro Image）提供工作室级控制；2 则把 Pro 上让人喜欢的世界知识、推理与规格，降到 Flash 速度，并成为 Gemini 应用 Fast / Thinking / Pro 模式的默认出图。Pro 与 Ultra 订阅仍可通过菜单把单张再生成走 Pro 档。开发者预览：Gemini API、AI Studio、Vertex、Antigravity；Search 的 AI Mode 与 Lens、Flow（零额度默认）、Google Ads 同期铺开。本篇只根据该博客、开发者图像文档与新闻稿式转述。不引用非官方权重拆解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/gemini-native-image">原生出图</a> 已经把对话改图做成 Gemini 的接口。用户仍面临档位分裂：Flash 够快但不够「像 Pro」，Pro 够强但慢、贵、且占默认入口会让普通用户付延迟。2 要解决的产品问题是：<strong>默认档是否能同时做信息图、多主体一致性、4K 与可读文字</strong>，而不把所有人赶到 Pro。Search 与 Lens 要的是低延迟示意图，不是影棚海报；Ads 与 Flow 要的是可迭代资产。官方把「高级世界知识 + 联网图像搜索接地」写成 2 从 Pro 继承的能力，用于特定主体与图表，而不是保证新闻级事实。</p><p>命名是引用陷阱。Nano Banana 起初是 2.5 Flash Image 的绰号；Pro 是 3 Pro Image；2 是 3.1 Flash Image。API 必须以 <code>gemini-3.1-flash-image</code>（及当时预览后缀）为准。把「香蕉」当唯一标识，三个月后会对错模型。Cloud 文档另列：每提示最多约 14 张输入图、输出分辨率从 512 到 4K 分档、输出按分辨率计图像 token（例如文档表里 1K 约 1120、4K 约 2520，以当时页为准）。</p><h3 id="默认替换-pro-是产品决策-不是「pro-已死」" tabindex="-1">默认替换 Pro 是产品决策，不是「Pro 已死」 <a class="header-anchor" href="#默认替换-pro-是产品决策-不是「pro-已死」" aria-label="Permalink to &quot;默认替换 Pro 是产品决策，不是「Pro 已死」&quot;">​</a></h3><p>博客写：2 在应用里替换各模式的 Pro 出图；付费用户仍可对已生成图走三点菜单用 Pro 做「需要最高事实准确性」的任务。分工被写成：Pro 最高保真与事实；2 快速、指令跟随、搜索接地。工程上应让用户或租户<strong>显式选 id</strong>，避免「我点了 Pro 聊天所以图也是 Pro 图像」。Search 铺到更多国家与语言，是分发，不是新损失。</p><p><span class="marginnote">SynthID 验证功能在 Gemini 应用自 2025-11 起的公开口径：超过 2000 万次使用。2 继续 SynthID，并推进与 C2PA Content Credentials 互操作，应用内 C2PA 校验「即将」提供——写时查是否已上线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>官方能力表。世界知识：Gemini 知识库 + 实时信息与网页图像，用于特定主体与信息图、笔记转示意图。文字：可读、可本地化翻译图内文案。主体一致性：工作流内最多约 <strong>5 个角色</strong> 像、约 <strong>14 个物体</strong> 保真（博客数字）。指令跟随：复杂请求更严。规格：多种宽高比，分辨率 <strong>512 到 4K</strong>。观感：光、纹理、细节在 Flash 速度下拉近。落地产品：Gemini 应用、Search/Lens、API 预览与定价页、Vertex、Flow 默认且对 Flow 用户零额度、Ads 建议图。</p><p>安全与来源：所有生成带 SynthID；与 C2PA 结合以说明是否以及如何使用了 AI。这不替代版权判断。真实人像与未成年人政策以产品条款为准，本篇不讨论绕过。定价：第三方报道曾转述相对 Pro 在高分辨率上约低四成的 API 价差，引用须核对 Google 当时价格表，不把新闻稿数字写成永久公式。</p>',12)),(n(),s(d,null,{default:o(()=>[m(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%20%C2%B7%20%E5%8F%AF%E9%80%89%E5%8F%82%E8%80%83%E5%9B%BE%22%5D%20--%3E%20NB2%5B%22Nano%20Banana%202%20%2F%20Gemini%203.1%20Flash%20Image%22%5D%0A%20%20SRCH%5B%22%E5%8F%AF%E9%80%89%EF%BC%9ASearch%20%E6%8E%A5%E5%9C%B0%22%5D%20--%3E%20NB2%0A%20%20NB2%20--%3E%20IMG%5B%22%E5%9B%BE%E5%83%8F%20512%E2%80%934K%22%5D%0A%20%20IMG%20--%3E%20WM%5B%22SynthID%20%C2%B7%20%E8%A7%84%E5%88%92%E4%B8%AD%E7%9A%84%20C2PA%22%5D%0A%20%20IMG%20--%3E%20APP%5B%22Gemini%20%C2%B7%20Search%20%C2%B7%20Flow%20%C2%B7%20Ads%20%C2%B7%20API%22%5D%0A%20%20PRO%5B%22Nano%20Banana%20Pro%22%5D%20-.-%3E%7C%22%E4%BB%98%E8%B4%B9%E7%94%A8%E6%88%B7%E6%8C%89%E9%9C%80%E5%86%8D%E7%94%9F%E6%88%90%22%7C%20APP%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="接地会改变「画错」的形状" tabindex="-1">接地会改变「画错」的形状 <a class="header-anchor" href="#接地会改变「画错」的形状" aria-label="Permalink to &quot;接地会改变「画错」的形状&quot;">​</a></h3><p>无接地时，错误是训练先验里的张冠李戴。有搜索接地时，错误变成检索到的图被误用、或过时页面。官方示例包括先搜视觉参考再生成（如某博物馆的立体主义风格）。评测应分：纯文本想象、需事实的信息图、需身份一致的故事板。把接地打开的 Arena 分与关掉的混报，合同无效。延迟上，接地多一跳，与「Flash 速度」叙事可能冲突，产品应报分位延迟而不是只报不含搜索的实验室数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>2 仍是 Gemini 原生图像模态：同一模型家族做理解与生成，而不是 Imagen 专用栈——<a href="https://ai.google.dev/gemini-api/docs/imagen" target="_blank" rel="noreferrer">Imagen 文档</a> 已引导迁移。Flash 相对 Pro：推理与采样预算更小，官方主张在指令跟随与迭代编辑上足够，把「最高事实准确性」留给 Pro。主体一致性是跨图的身份约束，失败模式是第五个角色塌、或物体计数超过约 14。4K 提高输出 token，账单与审核扫描成本上升。Search 接地把工具调用插入出图前缀，机制上与文本 Gemini 的搜索工具同构，只是结果用于像素。</p><p>与 2.5 Flash Image（第一代 Nano Banana）比：官方强调从「病毒式编辑」走到「生产规格 + 知识」。与 3 Pro Image 比：同能力集的速度档，而不是新的生成论。不要把 3.1 写成「换了全新扩散公式」——未公开。交错图文、多轮编辑的接口纪律见前一篇，2 继承该合同。</p><p><span class="marginnote">Cloud 模型卡：Live API 不支持该图像模型、结构化输出不支持等限制，说明「Flash 图像」不是万能 Gemini。出图与实时语音是不同端点。虚拟试穿一类能力若标 Not supported，不要当已上线功能写。</span></p><h3 id="默认全产品铺开会放大失败模式" tabindex="-1">默认全产品铺开会放大失败模式 <a class="header-anchor" href="#默认全产品铺开会放大失败模式" aria-label="Permalink to &quot;默认全产品铺开会放大失败模式&quot;">​</a></h3><p>Search 与 Ads 让错误示意图进入更高分发。水印帮助识别，不保证读者看见。信息图若接地失败，看起来会像官方资料。产品需要：可点的来源、易见的 AI 标记、企业关闭接地的开关。本篇只陈述官方来源机制，不提供去水印做法。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="绰号、模型-id、聊天套餐是三张表" tabindex="-1">绰号、模型 id、聊天套餐是三张表 <a class="header-anchor" href="#绰号、模型-id、聊天套餐是三张表" aria-label="Permalink to &quot;绰号、模型 id、聊天套餐是三张表&quot;">​</a></h3><p>集成钉 id 与日期。应用默认 2 之后，评测基线要重跑，不能沿用 2025-08 的 Nano Banana 分。Pro 仍在，适合印刷级与最高事实；2 适合迭代、Search、Ads。4K 与 14 图输入是上限不是免费午餐。地区可用性（Search 141 国等）以博客当时列表为准。</p><p>与视频：Flow 把 2 当默认<strong>图像</strong>模型，视频仍是 Veo 等另一契约。与实时视频交互：那边是帧输入，这边是图像输出。三者都叫 Gemini 生态，合同不同。</p><p><span class="marginnote">出处：Raisinghani，Google Blog，2026-02-26；Gemini API <em>Nano Banana image generation</em> 文档中的 3.1 Flash Image / 3 Pro Image 分档；对照 2025-08-26 Gemini 2.5 Flash Image 发布。仅公开博客与文档。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nano Banana 2 = Gemini 3.1 Flash Image，2026-02-26 起作为默认高速出图档。</li><li>继承 Pro 向的世界知识、文字、一致性与 512–4K 规格，并把 Search 接地写进工作流。</li><li>应用里替换默认 Pro 出图；Pro 仍可按需再生成。</li><li>来源用 SynthID，并推进 C2PA；钉模型 id 而不是绰号。</li><li>出处：Google Nano Banana 2 博客与 Gemini 图像生成文档。</li></ul>',15))])}const F=i(g,[["render",p]]);export{u as __pageData,F as default};
